		"title": "Sep 15, 2026: DHL expands its capabilities in Colombia through acquisition of Open Market - DHL Group",
		"publisher": "group.dhl.com",
		"url": "https://group.dhl.com/en/media-relations/press-releases/2026/dhl-expands-its-capabilities-in-colombia-through-acquisition-of-open-market.html",
		"kind": "website",
